89	                    // the group never closed: reject the run up to its first inner comma, and reparse every later
90	                    // comma-separated chunk as its own entry, so a trailing legal entry is not swallowed
91	                    entry = value.substring(entryStart, deepComma);
92	                    pos = deepComma;
93	                } else {
94	                    entry = value.substring(entryStart, pos);
95	                }
