123	    /**
124	     Validate one raw entry and return its trimmed spelling, or {@code null} when it is malformed. {@code balanced}
125	     reports whether the collected run ended at parenthesis depth zero; an unbalanced run can never be a valid media
126	     condition or length.
127	     <p>
128	     A media condition may span several parenthesized groups joined by keywords ({@code (min-width: 30em) and
129	     (orientation: landscape)}), so the length is located at the end of the entry: either a whitespace-free scalar
130	     suffix, or a balanced {@code calc(...)} group. Anything before it is the optional media condition.
131	     </p>
132	     */
133	    private static String validateEntry(String entry, boolean balanced) {
134	        String trimmed = stripQuotes(entry.trim()); // a quote pair delimiting this single entry
135	        if (trimmed.isEmpty() || !balanced) return null;
136	        if (containsUnsafeChar(trimmed)) return null;
137	        if (containsScriptFragment(trimmed)) return null;
