154	    /**
155	     Return the index at which the trailing length begins, or {@code -1} when the entry does not end in a recognizable
156	     length. A {@code calc(...)} length ends in a balanced {@code )} whose matching {@code (} is preceded by the word
157	     {@code calc} at a token boundary; any other ending must be a single whitespace-free scalar token.
158	     */
159	    private static int findLengthStart(String s) {
160	        int n = s.length();
161	        if (s.charAt(n - 1) == ')') {
162	            int depth = 0;
163	            int i = n - 1;
164	            do {
165	                char c = s.charAt(i);
166	                if (c == ')') depth++;
167	                else if (c == '(') depth--;
168	                i--;
169	            } while (i >= 0 && depth > 0);
