240	    /**
241	     Validate the body of a {@code calc()} expression: balanced parentheses, and only non-negative scalars with
242	     recognized units (or bare numbers) joined by the {@code + - * /} operators. There is no leading minus, no empty
243	     operand, no URL, no semicolon, and no brace.
244	     */
245	    private static boolean isValidCalcBody(String body) {
