        return numDiscarded == 0 && errorList.isEmpty();
    }

    /**
     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
     */
    private final class CleaningVisitor implements NodeVisitor {
        private int numDiscarded = 0;
        private final Element root;
        private Element destination; // current element to append nodes to

        private CleaningVisitor(Element root, Element destination) {
            this.root = root;
            this.destination = destination;
        }

        @Override public void head(Node source, int depth) {
            if (source instanceof Element) {
                Element sourceEl = (Element) source;

                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
                    ElementMeta meta = createSafeElement(sourceEl);
                    Element destChild = meta.el;
                    destination.appendChild(destChild);

                    numDiscarded += meta.numAttribsDiscarded;
                    destination = destChild;
                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
                    numDiscarded++;
                }
            } else if (source instanceof TextNode) {
                TextNode sourceText = (TextNode) source;
                TextNode destText = new TextNode(sourceText.getWholeText());
                destination.appendChild(destText);
            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
                DataNode sourceData = (DataNode) source;
                DataNode destData = new DataNode(sourceData.getWholeData());
                destination.appendChild(destData);
            } else { // else, we don't care about comments, xml proc instructions, etc
                numDiscarded++;
            }
        }

        @Override public void tail(Node source, int depth) {
            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
                destination = destination.parent(); // would have descended, so pop destination stack
            }
        }
    }

    private int copySafeNodes(Element source, Element dest) {
        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
        cleaningVisitor.traverse(source);
        return cleaningVisitor.numDiscarded;
    }

    private ElementMeta createSafeElement(Element sourceEl) {
        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
        String sourceTag = sourceEl.tagName();
        Attributes destAttrs = dest.attributes();
        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy

        int numDiscarded = 0;
        Attributes sourceAttrs = sourceEl.attributes();
        for (Attribute sourceAttr : sourceAttrs) {
            // srcset is structurally allowed like any attribute, but its value holds several candidate URLs which are
            // validated individually below, so it must not go through the ordinary whole-value protocol test. sizes
            // is handled the same way: it is structurally allowed, but its value is validated entry by entry.
            boolean specialAttr = SrcsetCleaner.isSrcset(sourceAttr)
                || (isResponsiveImage(sourceTag) && SizesCleaner.isSizes(sourceAttr.getKey()));
            boolean attrAllowed = specialAttr
                ? safelist.isAllowedAttribute(sourceTag, sourceEl, sourceAttr)
                : safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr);
            if (attrAllowed) { // will keep this attr
                String key = sourceAttr.getKey();
                String value = sourceAttr.getValue();

                if (SrcsetCleaner.isSrcset(sourceAttr)) {
                    // validate and rewrite each candidate instead of treating the whole value as one opaque URL
                    SrcsetCleaner.Result srcset = SrcsetCleaner.clean(sourceEl, value, safelist);
                    if (srcset.removed) { // no acceptable candidate: remove the attribute, never leave it empty
                        numDiscarded += 1 + srcset.droppedCandidates;
                        continue;
                    }
                    numDiscarded += srcset.droppedCandidates;
                    value = srcset.value;
                } else if (SizesCleaner.isSizes(key) && isResponsiveImage(sourceTag)) {
                    // validate and rewrite each size entry instead of keeping the opaque media/length list
                    SizesCleaner.Result sizes = SizesCleaner.clean(value);
                    if (sizes.removed) { // no acceptable entry: remove the attribute, never leave it empty
                        numDiscarded += 1 + sizes.droppedEntries;
                        continue;
                    }
                    numDiscarded += sizes.droppedEntries;
                    value = sizes.value;
                } else if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
                    value = sourceEl.absUrl(key);
                    if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
                        value = sourceAttr.getValue();
                }
                Range.AttributeRange range = sourceAttrs.sourceRange(key);
                destAttrs.put(key, value);
                NodeInternals.attributeRange(destAttrs, key, range);
            } else
                numDiscarded++;
        }

        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
        // special case for <a href rel=nofollow>, only apply to external links:
        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
            String href = sourceEl.absUrl("href");
            if (!href.isEmpty()) {
                try {
                    URL baseUrl = new URL(sourceEl.baseUri());
                    URL linkUrl = new URL(href);
                    String baseHost = baseUrl.getHost();
                    if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
                        enforcedAttrs.remove("rel");
                } catch (MalformedURLException ignored) {}
            }
        }

        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
        for (Attribute enforcedAttr : enforcedAttrs) {
            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
        }
        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
        return new ElementMeta(dest, numDiscarded);
    }

    /**
     The elements for which a {@code sizes} attribute has responsive-image meaning and is validated entry by entry.
     A {@code sizes} attribute on any other element keeps its ordinary whole-attribute safelist treatment.
     */
    private static boolean isResponsiveImage(String tagName) {
        return "img".equalsIgnoreCase(tagName) || "source".equalsIgnoreCase(tagName);
    }

    private static class ElementMeta {
        Element el;
        int numAttribsDiscarded;

        ElementMeta(Element el, int numAttribsDiscarded) {
            this.el = el;
            this.numAttribsDiscarded = numAttribsDiscarded;
        }
    }

