#!/usr/bin/env python3
# Coverage: whitelist gating -> runWhitelist -> sizes removed when not allowed.
# Entry grammar and top-level splitting -> runBoundary -> mixed valid/invalid entries, nested commas, calc, media.
# srcset security and element independence -> runBoundary -> unsafe candidate removed while sizes and safe candidate remain.
# source/img parity -> runParity -> identical cleaned sizes values.
# non-mutation and idempotence -> runStability -> input unchanged and repeated/reparsed cleaning stable.
# Counterexamples: taking only the first entry, splitting every comma, accepting negative/calc URL values,
# or letting sizes bypass srcset checks all fail explicit assertions below.
import os, sys, subprocess, tempfile, textwrap
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
workspace = os.path.abspath(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
java_source = r'''
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class SizesAcceptance {
  static void eq(String label, String expected, String actual) {
    System.out.println(label + " => " + actual);
    if (!expected.equals(actual)) throw new AssertionError(label + " expected=" + expected + " actual=" + actual);
  }
  static void ok(String label, boolean value, String actual) {
    System.out.println(label + " => " + actual);
    if (!value) throw new AssertionError(label + " observed=" + actual);
  }
  static Safelist imgSizes() { return Safelist.relaxed().addAttributes("img", "sizes"); }
  static Safelist picture() {
    return Safelist.relaxed().addTags("picture", "source")
      .addAttributes("img", "srcset", "sizes")
      .addAttributes("source", "srcset", "sizes", "media", "type");
  }
  static void runBoundary() {
    eq("whitelist", "<img>", Jsoup.clean("<img sizes='100px'>", Safelist.relaxed()));
    String mixed = Jsoup.clean("<img sizes='(min-width: 600px) 200px, calc(100vw - 20px), bad, 50%, (x) -5px'>", imgSizes());
    eq("mixed entries", "<img sizes=\"(min-width: 600px) 200px, calc(100vw - 20px), 50%\">", mixed);
    eq("nested comma", "<img sizes=\"50vw\">", Jsoup.clean("<img sizes='calc(100px, 200px), 50vw'>", imgSizes()));
    eq("unclosed resync", "<img sizes=\"100px, 200px, 300px\">", Jsoup.clean("<img sizes='100px, (min-width: 600px, 200px, 300px'>", imgSizes()));
    String unsafe = Jsoup.clean("<img sizes='100px' srcset='javascript:alert(1) 1x, http://example.com/a.jpg 2x'>", picture());
    System.out.println("srcset protocol => " + unsafe);
    ok("srcset protocol", unsafe.contains("sizes=\"100px\"") && unsafe.contains("http://example.com/a.jpg 2x") && !unsafe.contains("javascript:"), unsafe);
    String isolated = Jsoup.clean("<picture><source media='(min-width: 1px)' type='image/webp' sizes='bad'><img sizes='100px, bad' srcset='http://example.com/a.jpg 1x, javascript:x 2x' alt='ok'></picture>", picture());
    System.out.println("element independence => " + isolated);
    ok("element independence", isolated.contains("<source media=\"(min-width: 1px)\" type=\"image/webp\">") && isolated.contains("sizes=\"100px\"") && isolated.contains("srcset=\"http://example.com/a.jpg 1x\"") && !isolated.contains("javascript:"), isolated);
  }
  static void runParity() {
    String value = "(min-width: 600px) 200px, bad, calc(100vw - 20px), 50%";
    String i = Jsoup.clean("<img sizes='" + value + "'>", picture());
    String s = Jsoup.clean("<source sizes='" + value + "'>", picture());
    System.out.println("img => " + i);
    System.out.println("source => " + s);
    String expected = "<source sizes=\"(min-width: 600px) 200px, calc(100vw - 20px), 50%\">";
    eq("source/img parity", expected, s);
    eq("source/img parity mirrored", expected, i.replaceFirst("^<img", "<source"));
    eq("duplicate media order", "<img sizes=\"(min-width: 600px) 100px, (min-width: 600px) 200px\">", Jsoup.clean("<img sizes='(min-width: 600px) 100px, (min-width: 600px) 200px'>", imgSizes()));
  }
  static void runStability() {
    String html = "<picture><source sizes='(min-width: 600px) calc(100vw - 16px), bad, 50%' srcset='http://example.com/a.jpg 1x'><img sizes='(max-width: 400px) 100px, 200px, nope' src='http://example.com/f.jpg'></picture>";
    Cleaner cleaner = new Cleaner(picture());
    Document dirty = Jsoup.parseBodyFragment(html, "http://example.com/");
    String before = dirty.body().html();
    Document once = cleaner.clean(dirty);
    String first = once.body().html();
    String second = cleaner.clean(once).body().html();
    String reparsed = cleaner.clean(Jsoup.parse(first)).body().html();
    System.out.println("cleaned => " + first);
    System.out.println("recleaned => " + second);
    System.out.println("reparsed => " + reparsed);
    eq("idempotence", first, second);
    eq("serialize/reparse", first, reparsed);
    eq("input unchanged", before, dirty.body().html());
    ok("picture structure", once.select("picture > source").size() == 1 && once.select("picture > img").size() == 1, first);
  }
  public static void main(String[] args) {
    String which = args.length == 0 ? "all" : args[0];
    if (which.equals("all") || which.equals("boundary")) runBoundary();
    if (which.equals("all") || which.equals("parity")) runParity();
    if (which.equals("all") || which.equals("stability")) runStability();
  }
}
'''
with tempfile.TemporaryDirectory(prefix="sizes-check-") as td:
    src = os.path.join(td, "SizesAcceptance.java")
    with open(src, "w", encoding="utf-8") as f:
        f.write(textwrap.dedent(java_source))
    build = subprocess.run(["mvn", "-q", "-DskipTests", "compile"], cwd=workspace, text=True, capture_output=True)
    if build.returncode:
        sys.stdout.write(build.stdout); sys.stderr.write("ENVIRONMENT/BUILD FAILURE\n" + build.stderr); sys.exit(2)
    cp = os.path.join(workspace, "target", "classes")
    javac = subprocess.run(["javac", "-cp", cp, src], text=True, capture_output=True)
    if javac.returncode:
        sys.stdout.write(javac.stdout); sys.stderr.write("ENVIRONMENT/ADAPTER FAILURE\n" + javac.stderr); sys.exit(2)
    which = sys.argv[1] if len(sys.argv) > 1 else "all"
    if which not in ("all", "boundary", "parity", "stability"):
        print("ENVIRONMENT/ADAPTER FAILURE: unsupported case", file=sys.stderr); sys.exit(2)
    run = subprocess.run(["java", "-cp", td + os.pathsep + cp, "SizesAcceptance", which], text=True, capture_output=True)
    sys.stdout.write(run.stdout); sys.stderr.write(run.stderr); sys.exit(run.returncode)

