import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Probe {
    static Safelist sl() { return Safelist.relaxed().addAttributes("img","sizes"); }
    static void show(String v) {
        System.out.println("IN : [" + v.replace("\t","<TAB>").replace("\n","<LF>").replace("\u0000","<NUL>") + "]");
        System.out.println("OUT: " + Jsoup.clean("<img sizes='" + v + "'>", sl()));
    }
    public static void main(String[] a) {
        show("(x: http://evil.test) 50vw, 100vw");       // bare URL in media condition
        show("(x:https://evil.test/x) 50vw, 100vw");      // glued https url
        show("(x: ftp://h/y) 50vw, 100vw");
        show("//evil.test/x 50vw, 100vw");                // protocol-relative-ish (no parens)
        show("(x: javascript :alert(1)) 50vw, 100vw");    // space before colon
        show("(x: http://x) calc(100vw + 1px), 100vw");
        show("(aspect-ratio: 16/9) 100vw");               // slash ratio must stay legal
        show("(min-width: 30em) and (hover: hover) 100vw");
        show("100VW, 0PX, .5EM, 100%, 12.0CH");           // uppercase units
        show("calc(100vw - -20px), 100vw");               // negative operand after operator
        show("calc(100vw + -1px), 100vw");
        show("calc( -1px + 100vw), 100vw");
